def cli_error(message):
    sys.stderr.write('error: '+message+'\n\nUSAGE:\n    executable [FLAGS] [arguments]...\n\nFor more information try --help\n')
    return 1

def process(data,filename,flags,runtime,imported=False):
    lex=Lexer(data,filename).lex()
    if 'lex' in flags:
        print(SEPARATOR)
        for item in lex.events:
            if isinstance(item,tuple):
                p,msg=item
                print(f'Error: line {p.line}, column {p.col} - {msg}')
            else:print(f'{item.pos}:\t{item.show()}')
        print(SEPARATOR)
    parser=Parser(lex);nodes=parser.block()
    if 'ast' in flags:
        print(SEPARATOR);print('AST for '+filename)
        body=Formatter().body(nodes)
        if body:print(body)
        print(SEPARATOR)
    analyzer=Analyzer();analyzer.block(nodes)
    if 'program' in flags and not parser.errors and not analyzer.errors:
        print(SEPARATOR);print('Program for '+filename)
        f=Formatter(True);print(f.vars(analyzer.root))
        body=f.body(nodes)
        if body:print(body)
        print(SEPARATOR)
    sys.stdout.flush()
    errors=lex.errors+parser.errors
    errors.sort(key=lambda e:e[0].offset if e[0] is not None else 10**30)
    errors+=analyzer.errors
    if errors:
        for p,msg in errors:
            if p is None:sys.stderr.write('Error: '+msg+'\n')
            else:sys.stderr.write('Error: '+str(p)+' - '+msg+'\n')
        if imported:raise SystemExit(2)
        return 2,None
    if 'check' in flags:return 0,None
    return 0,runtime.run(nodes,analyzer.root)

def main():
    sys.setrecursionlimit(20000)
    flags=set();args=[];literal=False
    for arg in sys.argv[1:]:
        if literal:args.append(arg);continue
        if arg=='--':literal=True;continue
        if arg in ('--help','-h'):
            sys.stdout.write(HELP);return 0
        if arg in ('--version','-V'):
            print('Hush 0.1.4');return 0
        if arg in ('--lex','--ast','--program','--check'):
            name=arg[2:]
            if name in flags:return cli_error("The argument '"+arg+"' was provided more than once, but cannot be used multiple times")
            flags.add(name)
        elif arg.startswith('-') and arg!='-':
            return cli_error("Found argument '"+arg+"' which wasn't expected, or isn't valid in this context")
        else:args.append(arg)
    filename='<stdin>';data=None
    if args:
        try:
            with open(args[0],'rb') as f:data=f.read()
            filename=args.pop(0)
        except (OSError,ValueError):args=args[1:]
    if data is None:data=sys.stdin.buffer.read()
    runtime=Runtime(args)
    def load(data,path,rt):return process(data,path,flags,rt,True)[1]
    runtime.load=load
    try:return process(data,filename,flags,runtime)[0]
    except Panic as e:
        sys.stderr.write(str(e)+'\n');return 127
    except RecursionError:
        sys.stderr.write('stack overflow\n');return 127

if __name__=='__main__':
    sys.exit(main())
